'use strict';
const $=s=>document.querySelector(s),params=new URLSearchParams(location.search),repay=params.get('repay')==='1';
let page=0,query='',onlyDebt=params.get('debt')==='1'||repay,requestNumber=0,newId=null;
const format=value=>new Intl.NumberFormat('en-US').format(typeof value==='string'?BigInt(value):value);
function node(tag,text){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;return element;}
async function load(){if(!KashierData.loggedIn()){location.replace('auth.html?next='+encodeURIComponent('customers.html'+location.search));return;}const request=++requestNumber;$('#customers-status').textContent='خوێندنەوەی کڕیارەکان…';$('#customers-rows').replaceChildren();$('#customer-previous').disabled=true;$('#customer-next').disabled=true;try{const [result,summary]=await Promise.all([KashierData.listCustomers(query,page,onlyDebt),KashierData.getDebtSummary()]);if(request!==requestNumber)return;$('#debt-total').textContent=format(summary.balance);$('#debtor-count').textContent=format(summary.debtors);for(const customer of result.rows){const row=node('tr');for(const value of [customer.name,customer.phone||'—',format(customer.balance)])row.append(node('td',value));const action=node('td'),link=node('a',repay?'وەرگرتنەوەی قەرز':'حساب و مامەڵەکان');link.className='catalog-link';link.href='customer.html?id='+customer.id+(repay?'&action=repayment':'');action.append(link);row.append(action);$('#customers-rows').append(row);}$('#customers-status').textContent=result.rows.length?'':'هیچ کڕیارێک لەم لیستە نەدۆزرایەوە.';$('#customer-count').textContent='کڕیار: '+result.total+' · پەڕە: '+(page+1);$('#customer-previous').disabled=page===0;$('#customer-next').disabled=(page+1)*50>=result.total;}catch(e){if(request===requestNumber)$('#customers-status').textContent=e.message;}}
$('#only-debt').checked=onlyDebt;$('#customers-heading').textContent=repay?'وەرگرتنەوەی قەرز':onlyDebt?'لیستی قەرزەکان':'کڕیارەکان';$('#customer-search').addEventListener('submit',e=>{e.preventDefault();query=$('#customer-query').value;page=0;load();});$('#only-debt').addEventListener('change',()=>{onlyDebt=$('#only-debt').checked;page=0;load();});$('#customer-previous').addEventListener('click',()=>{if(page>0){page--;load();}});$('#customer-next').addEventListener('click',()=>{page++;load();});
$('#new-customer').addEventListener('click',()=>{newId=crypto.randomUUID();$('#customer-form').reset();$('#customer-error').textContent='';$('#customer-form-dialog').showModal();$('#customer-name').focus();});$('#customer-close').addEventListener('click',()=>{if(!$('#customer-save').disabled)$('#customer-form-dialog').close();});$('#customer-form-dialog').addEventListener('cancel',e=>{if($('#customer-save').disabled)e.preventDefault();});
$('#customer-form').addEventListener('submit',async e=>{e.preventDefault();if(!$('#customer-form').reportValidity()||$('#customer-save').disabled)return;$('#customer-save').disabled=true;try{const name=$('#customer-name').value.trim(),phone=$('#customer-phone').value.trim()||null;if(!name)throw new Error('ناوی کڕیار بنووسە.');const customer=await KashierData.createCustomer({name,phone},newId);location.href='customer.html?id='+customer.id;}catch(error){$('#customer-error').textContent=error.message;}finally{$('#customer-save').disabled=false;}});load();
